/bin/bash -lc 'set -euo pipefail
BASE=c56d433e8a99a82babf50aecb3e6fec48410e2a2
HEAD=$("$HORIZON_GIT" rev-parse HEAD)
TMP=$(mktemp -d)
trap '"'rm -rf \""'$TMP"'"' EXIT
for rev in \""'$BASE" "$HEAD"; do
  mkdir -p "$TMP/$rev"
  "$HORIZON_GIT" archive "$rev"     MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian     MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian     | tar -x -C "$TMP/$rev"
done
python - "$TMP" "$BASE" "$HEAD" <<'"'PY'
from pathlib import Path
import sys, json
from archon_horizon.search.index import extract_declarations

root, base, head = Path(sys.argv[1]), sys.argv[2], sys.argv[3]
projects = {
  \"AJC\": \"MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian\",
  \"AJCR\": \"MainProjects/Algebraic-Jacobian-Challenge-Rebuild/AlgebraicJacobian\",
}

def split_decl(sig):
    par = bra = brc = 0
    in_str = False
    esc = False
    for i, c in enumerate(sig):
        if in_str:
            if esc:
                esc = False
            elif c == \"\\\\\":
                esc = True
            elif c == '\"':
                in_str = False
            continue
        if c == '\"':
            in_str = True
        elif c == '(':
            par += 1
        elif c == ')':
            par = max(0, par - 1)
        elif c == '[':
            bra += 1
        elif c == ']':
            bra = max(0, bra - 1)
        elif c == '{':
            brc += 1
        elif c == '}':
            brc = max(0, brc - 1)
        elif c == ':' and par == bra == brc == 0:
            return sig[:i], sig[i+1:]
    return sig, \"\"

def census(rev, proj):
    p = root / rev / projects[proj]
    rows = []
    raw = 0
    for f in sorted(p.rglob(\"*.lean\")):
        text = f.read_text(errors=\"replace\")
        raw += text.count(\"(rep :\")
        rel = str(f.relative_to(root/rev))
        for d in extract_declarations(text, library=proj, file=rel):
            prefix, result = split_decl(d.signature)
            inp = prefix.count(\".RepresentableBy\")
            out = result.count(\".RepresentableBy\")
            if inp or out:
                rows.append({
                    \"name\": d.name, \"file\": rel, \"line\": d.line,
                    \"input\": inp, \"output\": out,
                    \"direct\": bool(out and not inp),
                    \"signature\": d.signature.replace(\"\\n\", \" \"),
                })
    return {
      \"raw_rep_binders\": raw,
      \"input_occurrences\": sum(x[\"input\"] for x in rows),
      \"input_declarations\": sum(bool(x[\"input\"]) for x in rows),
      \"result_declarations\": sum(bool(x[\"output\"]) for x in rows),
      \"direct_producers\": sum(x[\"direct\"] for x in rows),
      \"rows\": rows,
    }

allc = {(rev,p): census(rev,p) for rev in (base,head) for p in projects}
print(json.dumps({\"base\":base,\"head\":head}, indent=2))
for p in projects:
    b,h = allc[(base,p)], allc[(head,p)]
    keys = [\"raw_rep_binders\",\"input_occurrences\",\"input_declarations\",\"result_declarations\",\"direct_producers\"]
    print(\"\\n\"+p)
    for k in keys:
        print(f\"{k}: {b[k]} -> {h[k]} ({h[k]-b[k]:+d})\")
    bnames={(r[\"file\"],r[\"name\"],r[\"line\"],r[\"input\"],r[\"output\"]) for r in b[\"rows\"]}
    print(\"NEW_OR_CHANGED_DECLARATIONS\")
    for row in h[\"rows\"]:
        ident=(row[\"file\"],row[\"name\"],row[\"line\"],row[\"input\"],row[\"output\"])
        if ident not in bnames:
            print(json.dumps(row, ensure_ascii=True))
PY"

